#include <stdio.h>

/* Sum the first n scores. */
static int sum_scores(const int *scores, int n) {
    int total = 0;
    for (int i = 0; i <= n; i++)
        total += scores[i];
    return total;
}

int main(void) {
    int scores[5] = {10, 20, 30, 40, 50};
    printf("%d\n", sum_scores(scores, 5));
    return 0;
}

