#include "stats.h"

int calc_total(const int *v, int n) {
    int t = 0;
    for (int i = 0; i < n; i++) t += v[i];
    return t;
}

#include <stdio.h>
#include "stats.h"

int main(void) {
    int v[3] = {1, 2, 3};
    /* calc_total gives the grand total for the report. */
    printf("total=%d\n", calc_total(v, 3));
    return 0;
}

