#include <stdio.h>
#include <string.h>

/* header.bin comes from the build server: a 32-bit magic 0xFEEDFACE
 * followed by a 32-bit version number, both big-endian. */
int main(void) {
    unsigned char buf[8];
    FILE *f = fopen("header.bin", "rb");
    if (!f || fread(buf, 1, 8, f) != 8) {
        puts("read error");
        return 1;
    }
    fclose(f);
    unsigned int magic, version;
    memcpy(&magic, buf, 4);
    memcpy(&version, buf + 4, 4);
    if (magic != 0xFEEDFACE) {
        printf("bad magic %08x\n", magic);
        return 1;
    }
    printf("version %u\n", version);
    return 0;
}
